import 'package:material_ui/material_ui.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../data/doctor_repository.dart';class DoctorPatientPage extends ConsumerWidget{const DoctorPatientPage({super.key,required this.patientId});final String patientId;@override Widget build(BuildContext context,WidgetRef ref){final d=FutureProvider.autoDispose((ref)=>ref.watch(doctorRepositoryProvider).details(patientId));final x=ref.watch(d);return Scaffold(appBar:AppBar(title:const Text('ملف المريض')),body:x.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(_,_)=>const Center(child:Text('تعذر تحميل بيانات المريض.')),data:(p)=>ListView(padding:const EdgeInsets.all(20),children:[Text(p.name,style:Theme.of(context).textTheme.headlineSmall),Text(p.email),const SizedBox(height:20),Card(child:ListTile(title:const Text('آخر قراءة'),trailing:Text(p.lastReading?.toStringAsFixed(0)??'—'))),Card(child:ListTile(title:const Text('متوسط 7 أيام'),trailing:Text(p.average?.toStringAsFixed(0)??'—'))),Card(child:ListTile(title:const Text('ضمن النطاق'),trailing:Text((p.inRange?.toStringAsFixed(0)??'—')+'%'))),Card(child:ListTile(title:const Text('الاتجاه'),trailing:Text(_trend(p.trend)))),Card(child:ListTile(title:const Text('الأدوية النشطة'),trailing:Text(p.activeMeds.toString())),),Card(child:ListTile(title:const Text('التنبيهات غير المقروءة'),trailing:Text(p.unreadAlerts.toString())))]));}String _trend(String v)=>switch(v){ 'Improving'=>'تحسن','Worsening'=>'تراجع','Stable'=>'مستقر',_=>'غير كافٍ'};}